 for j in range(1,L):
  theta=math.pi*j/L
  for k in range(K):phi=2*math.pi*k/K;dirs.append((math.sin(theta)*math.cos(phi),math.sin(theta)*math.sin(phi),math.cos(theta)))
 south=len(dirs);dirs.append((0.,0.,-1.))
 for k in range(K):faces.append((0,1+k,1+(k+1)%K))
 for j in range(L-2):
  for k in range(K):a=1+j*K+k;b=1+j*K+(k+1)%K;c=a+K;d=b+K;faces.extend(((a,c,d),(a,d,b)))
 for k in range(K):faces.append((1+(L-2)*K+k,south,1+(L-2)*K+(k+1)%K))
 return np.array(dirs),np.array(faces,'i4')
